//! Native season combat. Arena identities preserve dead sources during recursive triggers.
use crate::{Result, abilities, arr, catalog, def, has, num, primitives, recruit::Recruit, stats, str_field, tribe, truth};
use serde_json::{Value,json};
use std::collections::HashMap;
use tavern_combat_prototype::Random;

#[derive(Clone,Default)]
pub(crate) struct Context { pub side:usize, pub target:Option<String>, pub event:Option<String>, pub killer:Option<String>, pub pos:Option<usize>, pub slot:Option<usize>, pub amount:f64, pub depth:u32 }
pub(crate) struct Combat {
 pub games:[Value;2], pub boards:[Vec<String>;2], pub cards:HashMap<String,Value>, pub rng:Random, pub serial:u64,
 pub pending:[Vec<Value>;2], pub flags:[HashMap<String,f64>;2], pub dead_mechs:[Vec<Value>;2], pub dead_aberrations:[Vec<Value>;2],
 pub retained:HashMap<String,f64>, pub killers:HashMap<String,String>, pub slots:Vec<(usize,usize)>, pub frames:Vec<Value>, pub record_frames:bool, pub logs:bool, pub other:bool,
}
pub(crate) fn uid(m:&Value)->String {m["uid"].as_str().unwrap_or("").to_owned()}
pub(crate) fn mc(m:&Value,k:&str)->f64 {num(&m["counters"][k])}
pub(crate) fn bump(m:&mut Value,k:&str,n:f64)->f64 {if !m["counters"].is_object(){m["counters"]=json!({});} let v=mc(m,k)+n;m["counters"][k]=json!(v);v}
pub(crate) fn kw(m:&Value,k:&str)->bool {arr(&m["keywords"]).iter().any(|x|x==k)}
pub(crate) fn keyword(m:&mut Value,k:&str) {let ks=m["keywords"].as_array_mut().unwrap();if !ks.iter().any(|x|x==k){ks.push(json!(k));}}
impl Combat {
 pub fn m(&self,id:&str)->&Value {&self.cards[id]}
 pub fn mm(&mut self,id:&str)->&mut Value {self.cards.get_mut(id).expect("arena identity")}
 pub fn board(&self,s:usize)->Vec<Value>{self.boards[s].iter().map(|id|self.m(id).clone()).collect()}
 pub fn index(&mut self,n:usize)->usize{(self.rng.next_u32() as f64 /4294967296. * n as f64).floor() as usize}
 pub fn pick<T:Clone>(&mut self,v:&[T])->Option<T>{let i=self.index(v.len());v.get(i).cloned()}
 pub fn shuffle<T>(&mut self,v:&mut [T]){for i in (1..v.len()).rev(){let j=self.index(i+1);v.swap(i,j);}}
 pub fn item(&self,s:usize,key:&str)->f64{arr(&self.games[s]["season"]["trinkets"]).iter().filter(|x|*x==key).count() as f64}
 pub fn trinket(&self,s:usize,key:&str)->f64{self.item(s,&format!("BG36_MagicItem_{key}"))}
 pub fn power(&self,s:usize,key:&str)->bool{arr(&self.games[s]["season"]["powers"]).iter().any(|x|x==&format!("s14_{key}"))}
 pub fn count(&self,s:usize,key:&str)->f64{num(&self.games[s]["season"]["counters"][key])}
 pub fn game_bump(&mut self,s:usize,key:&str,n:f64)->f64{let st=&mut self.games[s]["season"];bump(st,key,n)}
 pub fn make(&mut self,id:&str,golden:bool)->Result<Value>{self.serial=self.serial.checked_add(1).ok_or("UID overflow")?;primitives::make(id,&format!("native-{}",self.serial),golden,false)}
 pub fn copy(&mut self,m:&Value)->Result<Value>{let mut c=m.clone();c["uid"]=self.make(str_field(m,"id")?,false)?["uid"].clone();c["copies"]=json!({});c["reward"]=json!(false);Ok(c)}
 pub fn recruit<T>(&mut self,s:usize,f:impl FnOnce(&mut Recruit)->Result<T>)->Result<T>{let mut r=Recruit::new(&json!({"state":self.games[s],"seed":self.rng.state,"uidCounter":self.serial,"recordLogs":self.logs}))?;let v=f(&mut r)?;self.rng.state=r.rng.state;self.rng.draws+=r.rng.draws;self.serial=r.serial;self.games[s]=r.result(vec![])["state"].take();Ok(v)}
 pub fn original_add(&mut self,s:usize,id:&str,a:f64,h:f64){if s==1&&!self.other{return;}if let Some(m)=self.games[s]["board"].as_array_mut().unwrap().iter_mut().find(|m|m["uid"]==id){stats::add(m,a,h);}}
 pub fn add(&mut self,id:&str,a:f64,h:f64){if self.m(id)["id"]=="s14_BG36_205"{return;}stats::add(self.mm(id),a,h);if let Some(f)=self.retained.get(id).copied(){for s in 0..2{self.original_add(s,id,a*f,h*f);}}}
 pub fn permanent(&mut self,s:usize,id:&str,a:f64,h:f64){if !self.retained.contains_key(id){self.original_add(s,id,a,h);}}
 pub fn remember(&mut self,s:usize,id:&str,key:&str,n:f64){if let Some(m)=self.games[s]["board"].as_array_mut().unwrap().iter_mut().find(|m|m["uid"]==id){bump(m,key,n);}}
 pub fn sync(&mut self,s:usize)->Result<()>{self.recruit(s,|r|r.sync_all())?;let mut state=self.games[s].clone();state["board"]=json!(self.board(s));for id in self.boards[s].clone(){let before=self.m(&id).clone();let next=stats::sync(&state,before.clone(),true)?;let a=num(&next["attack"])-num(&before["attack"]);let h=num(&next["health"])-num(&before["health"]);self.cards.insert(id.clone(),next);if let Some(f)=self.retained.get(&id).copied(){self.original_add(s,&id,a*f,h*f);}}Ok(())}
 pub fn frame(&mut self,text:String,attacker:Option<&str>,target:Option<&str>){if !self.record_frames{return;}let mut f=json!({"allies":self.board(0),"enemies":self.board(1),"text":text});if let Some(a)=attacker{f["attacker"]=json!(a);}if let Some(t)=target{f["target"]=json!(t);}self.frames.push(f);}
 pub fn summon(&mut self,s:usize,mut m:Value,pos:usize)->Result<()>{if self.boards[s].len()>=7{return Ok(());}let awaken=mc(&m,"pendingDeityAwaken")!=0.;if awaken{m["attack"]=self.games[s]["season"]["deity"]["attack"].clone();m["health"]=self.games[s]["season"]["deity"]["health"].clone();m["counters"]["pendingDeityAwaken"]=json!(0);}let pos=pos.min(self.boards[s].len());let id=uid(&m);self.boards[s].insert(pos,id.clone());for slot in &mut self.slots{if slot.0==s&&slot.1>=pos{slot.1+=1;}}let health=num(&m["health"]);bump(&mut m,"deathStatsHealth",health-mc(self.cards.get(&id).unwrap_or(&Value::Null),"deathStatsHealth"));m["counters"]["deathStatsHealth"]=json!(health);self.cards.insert(id.clone(),m);self.notify(s,&id)?;if awaken{self.run(&Context{side:s,..Default::default()},&id,"awaken")?;self.frame(format!("{}被唤醒。",def(str_field(self.m(&id),"id")?)?["name"].as_str().unwrap()),None,None);}Ok(())}
 pub fn summon_ctx(&mut self,c:&Context,m:Value,pos:usize)->Result<()>{let p=c.slot.map(|slot|self.slots[slot].1).unwrap_or(pos);self.summon(c.side,m,p)}
 pub fn notify(&mut self,s:usize,id:&str)->Result<()>{let c=Context{side:s,event:Some(id.to_owned()),..Default::default()};for x in self.boards[s].clone(){self.run(&c,&x,"summonAny")?;}self.trinket_event(&c,"summon")?;if self.power(s,"greybough"){self.gain(&c,None,id,1.,2.)?;keyword(self.mm(id),"嘲讽");}if self.m(id)["id"]=="s14_BG_TTN_401"{self.game_bump(s,"automatonSummons",1.);bump(self.mm(id),"automatonSelf",1.);self.sync(s)?;}for x in self.boards[s].clone(){if x==id{continue;}self.run(&c,&x,"summonCombat")?;if tribe(self.m(id),"野兽")?{self.run(&c,&x,"summonBeast")?;self.run(&c,&x,"summonBeastCombat")?;}if tribe(self.m(id),"机械")?{self.run(&c,&x,"summonMechCombat")?;}}Ok(())}
 pub fn damage(&mut self,id:&str,amount:f64,source:Option<&str>)->Result<()>{if amount<=0.{return Ok(());}if kw(self.m(id),"圣盾"){if has(self.m(id),"tripleShield")?{let limit=if truth(&self.m(id)["golden"]){4.}else{3.};if bump(self.mm(id),"shieldHits",1.)<limit{return Ok(());}}if self.m(id)["counters"].is_object(){self.mm(id)["counters"]["shieldHits"]=json!(0);}self.mm(id)["keywords"].as_array_mut().unwrap().retain(|k|k!="圣盾");for s in 0..2{if self.boards[s].iter().any(|x|x==id){let c=Context{side:s,event:Some(id.to_owned()),..Default::default()};for x in self.boards[s].clone(){self.run(&c,&x,"shieldLost")?;}}}return Ok(());}self.mm(id)["health"]=json!(num(&self.m(id)["health"])-amount);if let Some(src)=source{if kw(self.m(src),"剧毒")||kw(self.m(src),"烈毒"){self.mm(id)["health"]=json!(0);self.mm(src)["keywords"].as_array_mut().unwrap().retain(|k|k!="烈毒");}}for s in 0..2{if self.boards[s].iter().any(|x|x==id){self.run(&Context{side:s,amount,event:source.map(str::to_owned),..Default::default()},id,"damaged")?;}}if let Some(src)=source{let side=(0..2).find(|s|self.boards[*s].iter().any(|x|x==src));if let Some(s)=side{let c=Context{side:s,amount,target:Some(id.to_owned()),..Default::default()};self.run(&c,src,"dealtDamage")?;if tribe(self.m(src),"恶魔")?{for x in self.boards[s].clone(){if x!=src&&num(&self.m(&x)["health"])>0.{self.run(&Context{event:Some(src.to_owned()),..c.clone()},&x,"demonDamage")?;}}}}if num(&self.m(id)["health"])<=0.{self.killers.insert(id.to_owned(),src.to_owned());if let Some(s)=side{if self.power(s,"rokara"){self.add(src,1.,0.);self.permanent(s,src,1.,0.);}}}}Ok(())}
 pub fn death(&mut self,c:&Context,id:&str)->Result<()>{let has_death=abilities(self.m(id))?.iter().any(|a|a["event"]=="death");let repeat=self.boards[c.side].iter().filter(|x|has(self.m(x),"repeatAllTriggers").unwrap_or(false)).map(|x|if truth(&self.m(x)["golden"]){3}else{2}).max().unwrap_or(1);let titus=self.boards[c.side].iter().filter(|x|num(&self.m(x)["health"])>0.&&has(self.m(x),"titus").unwrap_or(false)).map(|x|if truth(&self.m(x)["golden"]){2}else{1}).sum::<usize>();let extra=if has_death&&!self.flags[c.side].contains_key("firstDeathrattle"){self.item(c.side,"BG30_MagicItem_700") as usize}else{0};if has_death{self.flags[c.side].insert("firstDeathrattle".into(),1.);}for _ in 0..repeat+titus+extra{self.run(c,id,"death")?;self.gift(c,id,"death")?;if has_death{self.game_bump(c.side,"deathrattles",1.);self.sync(c.side)?;for x in self.boards[c.side].clone(){self.run(&Context{event:Some(id.to_owned()),..c.clone()},&x,"deathTriggered")?;}}}Ok(())}
 pub fn fill(&mut self)->Result<()>{for s in 0..2{let c=Context{side:s,..Default::default()};if self.boards[s].is_empty(){self.trinket_event(&c,"empty")?;}if self.boards[s].len()<7&&truth(&self.games[s]["season"]["heroMarks"]["tavishId"]){self.games[s]["season"]["heroMarks"].as_object_mut().unwrap().remove("tavishId");if let Some(t)=self.pick(&self.boards[1-s].clone()){self.damage(&t,self.count(s,"tavishAttack"),None)?;}}while !self.pending[s].is_empty()&&self.boards[s].len()<7{let m=self.pending[s].remove(0);self.summon(s,m,self.boards[s].len())?;}for key in ["drekthar","vanndar"]{if truth(&self.games[s]["season"]["combatEffects"][key])&&!self.boards[s].is_empty()&&self.boards[s].len()<7{self.games[s]["season"]["combatEffects"][key]=json!(0);let stat=if key=="drekthar"{"attack"}else{"health"};let mut b=self.board(s);b.sort_by(|a,b|num(&b[stat]).total_cmp(&num(&a[stat])));let mut m=b[0].clone();m["uid"]=self.make(str_field(&m,"id")?,false)?["uid"].clone();m["copies"]=json!({});self.summon(s,m,self.boards[s].len())?;}}while num(&self.games[s]["season"]["combatEffects"]["beetles"])>0.&&self.boards[s].len()<7{self.games[s]["season"]["combatEffects"]["beetles"]=json!(num(&self.games[s]["season"]["combatEffects"]["beetles"])-1.);let m=self.make("s14_BG28_603t",false)?;let mut m=stats::global(&self.games[s],m)?;keyword(&mut m,"嘲讽");self.summon(s,m,self.boards[s].len())?;}}Ok(())}
 pub fn resolve_deaths(&mut self)->Result<()>{for _ in 0..100{let mut dead=vec![];for s in 0..2{let mut pos=0;for id in &self.boards[s]{if num(&self.m(id)["health"])<=0.{dead.push((s,pos,id.clone()));}else{pos+=1;}}}if dead.is_empty(){break;}self.slots=dead.iter().map(|(s,p,_)|(*s,*p)).collect();for (s,_,id) in &dead{self.boards[*s].retain(|x|x!=id);}for (slot,(s,_,id)) in dead.into_iter().enumerate(){let m=self.m(&id).clone();for k in 0..if self.other{2}else{1}{let d=self.games[k]["season"]["lastDead"].as_array_mut().unwrap();if d.len()<100{d.push(m["id"].clone());}}if tribe(&m,"机械")?{self.dead_mechs[s].push(json!({"id":m["id"],"golden":m["golden"]}));}if tribe(&m,"畸变怪")?&&! ["BGFYM_000","BGFYM_011"].iter().any(|id|def(m["id"].as_str().unwrap()).unwrap()["sourceId"]==*id){self.dead_aberrations[s].push(m.clone());}self.games[s]["season"]["deaths"]=json!(num(&self.games[s]["season"]["deaths"])+1.);if self.dead_aberrations[s].len()>=3&&!self.flags[s].contains_key("deityAwakened")&&truth(&self.games[s]["season"]["deity"]){self.flags[s].insert("deityAwakened".into(),1.);let d=self.games[s]["season"]["deity"].clone();let mut card=self.make(&format!("s14_{}",str_field(&d,"id")?),truth(&d["golden"]))?;card["attack"]=d["attack"].clone();card["health"]=d["health"].clone();card["counters"]=json!({"awakenedDeity":1,"pendingDeityAwaken":1});if self.trinket(s,"416")>0.{keyword(&mut card,"复生");}if self.boards[s].len()<7{self.summon(s,card,self.boards[s].len())?;}else{self.pending[s].insert(0,card);}}let c=Context{side:s,event:Some(id.clone()),pos:Some(self.slots[slot].1),slot:Some(slot),killer:self.killers.get(&id).cloned(),..Default::default()};self.trinket_event(&c,"death")?;if self.power(s,"ini")&&num(&self.games[s]["season"]["deaths"])%9.==0.{self.recruit(s,|r|{let tier=num(&r.state["tier"]);if let Some(m)=r.draw(|d|num(&d["tier"])<=tier&&(arr(&d["races"]).iter().any(|t|t=="机械")||d["tribe"]=="全部"))?{r.put_hand(m,true)?;}Ok(())})?;}let enemy=1-s;if self.power(enemy,"rafaam")&&self.count(enemy,"rafaamTurn")==num(&self.games[enemy]["turn"])&&self.count(enemy,"rafaamClaim")!=num(&self.games[enemy]["turn"]){let card=self.make(str_field(&m,"id")?,false)?;self.recruit(enemy,|r|r.put_hand(card,true))?;self.games[enemy]["season"]["counters"]["rafaamClaim"]=self.games[enemy]["turn"].clone();}for fish in self.boards[s].clone(){if self.m(&fish)["id"]=="s14_TB_BaconShop_HP_105t"&&fish!=id{for _ in 0..if truth(&self.m(&fish)["golden"]){2}else{1}{let copied:Vec<Value>=abilities(&m)?.iter().filter(|a|a["event"]=="death").map(|a|primitives::copy_ability(&m,a)).collect::<Result<Vec<_>>>()?;if !self.m(&fish)["extraAbilities"].is_array(){self.mm(&fish)["extraAbilities"]=json!([]);}self.mm(&fish)["extraAbilities"].as_array_mut().unwrap().extend(copied);}}}if m["id"]=="s14_BG25_008"{self.game_bump(s,"knightDeaths",1.);self.sync(s)?;}if tribe(&m,"亡灵")?&&self.trinket(s,"216")>0.{let n=self.trinket(s,"216");self.scale(s,"eternalPortrait",4.*n,2.*n)?;self.sync(s)?;}self.death(&c,&id)?;for x in self.boards[s].clone(){if num(&self.m(&x)["health"])<=0.{continue;}self.run(&Context{slot:None,event:Some(id.clone()),..c.clone()},&x,"friendlyDeath")?;let n=bump(self.mm(&x),"avengeDeaths",1.);for a in abilities(self.m(&x))?.into_iter().filter(|a|a["event"]=="avenge"){if n%a["threshold"].as_f64().unwrap_or(1.)==0.{self.effect(&Context{slot:None,event:Some(id.clone()),..c.clone()},&x,&a)?;}}}if kw(&m,"复生"){let card=self.make(str_field(&m,"id")?,truth(&m["golden"]))?;let mut card=stats::global(&self.games[s],card)?;card["health"]=json!(1);card["keywords"].as_array_mut().unwrap().retain(|k|k!="复生");let revived=uid(&card);self.summon(s,card,self.slots[slot].1)?;if !self.boards[s].contains(&revived){continue;}for x in self.boards[s].clone(){if num(&self.m(&x)["health"])>0.{self.run(&Context{side:s,event:Some(revived.clone()),..Default::default()},&x,"reborn")?;}}let n=self.trinket(s,"205");if (s==0||self.other)&&n>0.{for x in self.boards[s].clone(){self.add(&x,2.*n,2.*n);}}if self.trinket(s,"217")>0.&&self.flags[s].get("rebornCopies").copied().unwrap_or(0.)<3.{*self.flags[s].entry("rebornCopies".into()).or_default()+=1.;for _ in 0..self.trinket(s,"217") as usize{let card=self.make(str_field(&m,"id")?,truth(&m["golden"]))?;self.recruit(s,|r|r.trinket_card(card))?;}}}}self.slots.clear();self.fill()?;}Ok(())}
}
impl Combat {
 fn start(&mut self)->Result<()>{self.frame("战斗开始".into(),None,None);for s in 0..2{let c=Context{side:s,..Default::default()};self.trinket_event(&c,"combat")?;if self.power(s,"ozumat"){let mut token=self.make("s14_BG23_HERO_201pt",false)?;let n=self.count(s,"power:ozumat:soldMinions");stats::add(&mut token,n,n);self.pending[s].push(token);}for key in ["drekthar","vanndar"]{if self.power(s,key)&&num(&self.games[s]["turn"])>=7.{if !self.games[s]["season"]["combatEffects"].is_object(){self.games[s]["season"]["combatEffects"]=json!({});}self.games[s]["season"]["combatEffects"][key]=json!(1);}}if self.power(s,"yshaarj")&&self.count(s,"yshaarjTurn")==num(&self.games[s]["turn"])&&self.boards[s].len()<7{let card=self.recruit(s,|r|{let tier=num(&r.state["tier"]);let card=r.draw(|d|num(&d["tier"])==tier)?;if let Some(m)=&card{r.put_hand(m.clone(),true)?;}Ok(card)})?;if let Some(mut card)=card{card["uid"]=self.make(str_field(&card,"id")?,false)?["uid"].clone();card["copies"]=json!({});self.summon(s,card,self.boards[s].len())?;}}if self.power(s,"tamsin"){let mut b=self.board(s);b.sort_by(|a,b|num(&a["attack"]).total_cmp(&num(&b["attack"])));if let Some(t)=b.first(){let id=uid(t);if !self.m(&id)["extraAbilities"].is_array(){self.mm(&id)["extraAbilities"]=json!([]);}self.mm(&id)["extraAbilities"].as_array_mut().unwrap().push(json!({"event":"death","op":"deathStats","target":"others"}));let health=self.m(&id)["health"].clone();self.mm(&id)["counters"]["deathStatsHealth"]=health;}}if self.power(s,"teron"){if let Some(id)=self.games[s]["season"]["heroMarks"]["teron"].as_str().map(str::to_owned){if self.boards[s].contains(&id){let mut copy=self.m(&id).clone();copy["uid"]=self.make(str_field(&copy,"id")?,false)?["uid"].clone();copy["copies"]=json!({});self.pending[s].push(copy);self.mm(&id)["health"]=json!(0);}self.games[s]["season"]["heroMarks"].as_object_mut().unwrap().remove("teron");}}if self.power(s,"waggtoggle"){let n=1.+(self.count(s,"power:waggtoggle:goldSpent")/10.).floor();let dummy=self.make("s14_BG25_001",false)?;let id=uid(&dummy);self.cards.insert(id.clone(),dummy);for x in self.targets(&c,&id,&json!({"target":"menagerie"}))?{self.gain(&c,None,&x,n,n)?;}}if self.power(s,"deathwing"){for side in 0..2{for id in self.boards[side].clone(){self.add(&id,2.,0.);self.permanent(side,&id,2.,0.);}}}for card in arr(&self.games[s]["hand"]).to_vec(){let id=uid(&card);self.cards.insert(id.clone(),card);self.run(&c,&id,"handCombat")?;}let effects=self.games[s]["season"]["combatEffects"].clone();for _ in 0..num(&effects["enemyOne"]) as usize{if let Some(id)=self.pick(&self.boards[1-s].clone()){self.mm(&id)["health"]=json!(1);}}if truth(&effects["doubleLeft"]){if let Some(id)=self.boards[s].first().cloned(){self.mm(&id)["attack"]=json!(num(&self.m(&id)["attack"])*2f64.powf(num(&effects["doubleLeft"])));}}for id in self.boards[s].clone(){self.run(&c,&id,"combat")?;self.gift(&c,&id,"combat")?;}if (s==0||self.other)&&self.power(s,"alakir"){if let Some(id)=self.boards[s].first().cloned(){for k in ["风怒","圣盾","嘲讽"]{keyword(self.mm(&id),k);}}}if (s==0||self.other)&&self.trinket(s,"213")>0.{for id in self.boards[s].clone(){if abilities(self.m(&id))?.iter().any(|a|a["event"]=="rally"){keyword(self.mm(&id),"圣盾");}}}if (s==0||self.other)&&self.trinket(s,"361")>0.{let ids:Vec<_>=self.boards[s].iter().filter(|x|tribe(self.m(x),"纳迦").unwrap_or(false)).cloned().collect();if let Some(first)=ids.first(){self.add(first,num(&self.m(first)["attack"]),num(&self.m(first)["health"]));}if ids.len()>1{let last=ids.last().unwrap();self.add(last,num(&self.m(last)["attack"]),num(&self.m(last)["health"]));}}if self.trinket(s,"841")>0.{return Err("RUST_COMBAT_MAGNETIZE_INCOMPLETE: BG36_MagicItem_841".into());}}self.fill()?;self.resolve_deaths()?;self.frame("战斗开始技能结算".into(),None,None);Ok(())}
 fn fight(&mut self,enemy_tier:f64)->Result<Value>{self.start()?;let mut side=if self.boards[0].len()==self.boards[1].len(){self.index(2)}else if self.boards[0].len()>self.boards[1].len(){0}else{1};let mut last=[String::new(),String::new()];let mut indices=[0,0];for _ in 0..180{if self.boards[0].is_empty()||self.boards[1].is_empty(){break;}let normal=side;let immediate_side=[side,1-side].into_iter().find(|s|self.boards[*s].iter().any(|id|num(&self.m(id)["health"])>0.&&num(&self.m(id)["attack"])>0.&&mc(self.m(id),"immediateAttack")!=0.));if let Some(s)=immediate_side{side=s;}let immediate=self.boards[side].iter().find(|id|num(&self.m(id)["health"])>0.&&num(&self.m(id)["attack"])>0.&&mc(self.m(id),"immediateAttack")!=0.).cloned();if let Some(id)=&immediate{bump(self.mm(id),"immediateAttack",-1.);}let b=&self.boards[side];let start=b.iter().position(|x|x==&last[side]).map(|i|(i+1)%b.len()).unwrap_or(indices[side]%b.len());let attacker=(0..b.len()).map(|i|b[(start+i)%b.len()].clone()).find(|id|num(&self.m(id)["attack"])>0.);let Some(mut attack)=attacker else{if !self.boards[1-side].iter().any(|id|num(&self.m(id)["attack"])>0.){break;}side=1-side;continue;};if let Some(id)=&immediate{attack=id.clone();}else{last[side]=attack.clone();indices[side]=self.boards[side].iter().position(|x|x==&attack).unwrap();}let swings=if immediate.is_none()&&kw(self.m(&attack),"风怒"){2}else{1};for _ in 0..swings{if num(&self.m(&attack)["health"])<=0.||self.boards[1-side].is_empty(){break;}let c=Context{side,event:Some(attack.clone()),..Default::default()};self.trinket_event(&c,"attack")?;if tribe(self.m(&attack),"野兽")?&&self.trinket(side,"201")>0.{let n=self.trinket(side,"201");self.gain(&c,None,&attack,4.*n,2.*n)?;}self.game_bump(side,"heroAttacks",1.);for power in crate::powers::equipped(&self.games[side]){if let Some(key)=power.as_str(){self.game_bump(side,&format!("power:{}:attacks",key.strip_prefix("s14_").unwrap_or(key)),1.);}}if self.power(side,"lo")&&self.count(side,"power:lo:attacks")%15.==0.{self.recruit(side,|r|r.reward(None))?;}let mut enemy:Vec<_>=self.boards[1-side].iter().filter(|id|!kw(self.m(id),"潜行")).cloned().collect();if enemy.is_empty(){enemy=self.boards[1-side].clone();}let taunts:Vec<_>=enemy.iter().filter(|id|kw(self.m(id),if self.m(id)["id"]=="s14_BG34_405"{"圣盾"}else{"嘲讽"})).cloned().collect();let target=self.pick(if taunts.is_empty(){&enemy}else{&taunts}).unwrap();let c=Context{target:Some(target.clone()),pos:self.boards[side].iter().position(|x|x==&attack),..c};self.run(&c,&attack,"rally")?;if num(&self.m(&target)["health"])<=0.{self.resolve_deaths()?;self.frame("进击、伤害与亡语结算".into(),None,None);continue;}self.gift(&Context{target:None,..c.clone()},&attack,"rally")?;for x in self.boards[side].clone(){if x!=attack{self.run(&Context{target:None,..c.clone()},&x,"otherAttack")?;}if tribe(self.m(&attack),"野兽")?{self.run(&Context{target:None,..c.clone()},&x,"attackBeast")?;}if x!=attack&&tribe(self.m(&attack),"龙")?{self.run(&Context{target:None,..c.clone()},&x,"attackDragon")?;}}if (side==0||self.other)&&self.trinket(side,"200")>0.&&abilities(self.m(&attack))?.iter().any(|a|a["event"]=="rally"){self.games[side]["season"]["freeRefresh"]=json!(num(&self.games[side]["season"]["freeRefresh"])+self.trinket(side,"200"));}let adjacent=|this:&Self|->Vec<String>{let i=this.boards[1-side].iter().position(|x|x==&target).unwrap();[i.checked_sub(1),Some(i+1)].into_iter().flatten().filter_map(|i|this.boards[1-side].get(i).cloned()).collect()};let neighbors=if has(self.m(&attack),"cleave")?{adjacent(self)}else{vec![]};for x in self.boards[1-side].clone(){self.run(&Context{side:1-side,event:Some(target.clone()),..Default::default()},&x,"attacked")?;}let a=num(&self.m(&attack)["attack"]);let t=num(&self.m(&target)["attack"]);let health=num(&self.m(&target)["health"]);let shield=kw(self.m(&target),"圣盾");self.damage(&target,a,Some(&attack))?;if num(&self.m(&target)["health"])<=0.{self.run(&Context{side,event:Some(target.clone()),..Default::default()},&attack,"kill")?;}if has(self.m(&attack),"overkillAdjacent")?&&!shield&&num(&self.m(&target)["health"])<=0.&&a>health{let neighbors=adjacent(self);let victims=if truth(&self.m(&attack)["golden"]){neighbors}else{self.pick(&neighbors).into_iter().collect()};for x in victims{self.damage(&x,a-health,Some(&attack))?;}}if !has(self.m(&attack),"immuneAttack")?&&self.m(&attack)["gift"]!="BG36_MidGameEffect_000t60"{self.damage(&attack,t,Some(&target))?;}for x in neighbors{self.damage(&x,a,Some(&attack))?;}for x in self.boards[side].clone(){if num(&self.m(&x)["health"])>0.{self.run(&Context{side,event:Some(attack.clone()),..Default::default()},&x,"afterAttack")?;}}self.mm(&attack)["keywords"].as_array_mut().unwrap().retain(|k|k!="潜行");let text=format!("{} 攻击 {}",def(str_field(self.m(&attack),"id")?)?["name"].as_str().unwrap(),def(str_field(self.m(&target),"id")?)?["name"].as_str().unwrap());self.frame(text,Some(&attack),Some(&target));self.resolve_deaths()?;self.frame("进击、伤害与亡语结算".into(),None,None);}side=if immediate.is_some(){normal}else{1-side};}let result=if !self.boards[0].is_empty()&&self.boards[1].is_empty(){"win"}else if !self.boards[1].is_empty()&&self.boards[0].is_empty(){"loss"}else{"tie"};let raw=if result=="tie"{0.}else{let winner=if result=="win"{0}else{1};let tier=if winner==0{num(&self.games[0]["tier"])}else{enemy_tier};tier+self.boards[winner].iter().map(|id|num(&def(self.m(id)["id"].as_str().unwrap()).unwrap()["tier"])).sum::<f64>()};let living=arr(&self.games[0]["opponents"]).iter().filter(|o|num(&o["health"])>0.).count()+1;let turn=num(&self.games[0]["turn"]);let cap=if living<=4{f64::INFINITY}else if turn<4.{5.}else if turn<8.{10.}else{15.};let amount=raw.min(cap);for side in 0..2{let confidence=num(&self.games[side]["season"]["combatEffects"]["confidence"]);if confidence!=0.{let won=if side==0{result=="win"}else{result=="loss"};self.games[side]["season"]["nextGold"]=json!(num(&self.games[side]["season"]["nextGold"])+confidence*if won{3.}else if result=="tie"{1.}else{0.});}self.games[side]["season"]["combatEffects"]=json!({});}self.games[0]["season"]["buffs"]["beastCombat"]=json!({"attack":0,"health":0});if self.other{self.games[1]["season"]["buffs"]["beastCombat"]=json!({"attack":0,"health":0});}self.frame(format!("{} · {}点伤害{}",if result=="win"{"胜利"}else if result=="loss"{"失利"}else{"平局"},amount,if raw>cap{"，已应用伤害上限"}else{""}),None,None);Ok(json!({"frames":self.frames,"result":result,"damage":amount,"opponent":""}))}
}
pub fn resolve(request:&Value)->Result<Value>{let s=request["state"].clone();let other=request["other"].is_object();let mut enemy=if other{request["other"].clone()}else{s.clone()};if !other{enemy["hand"]=json!([]);enemy["shop"]=json!([]);for key in ["buffs","counters","combatEffects"]{enemy["season"][key]=json!({});}for key in ["trinkets","powers"]{enemy["season"][key]=json!([]);}}let rng=request["seed"].as_u64().filter(|n|*n<=u32::MAX as u64).ok_or("Seed must be uint32")?;let mut combat=Combat{games:[s,enemy],boards:[vec![],vec![]],cards:HashMap::new(),rng:Random::new(rng as u32),serial:request["uidCounter"].as_u64().unwrap_or(0),pending:[vec![],vec![]],flags:[HashMap::new(),HashMap::new()],dead_mechs:[vec![],vec![]],dead_aberrations:[vec![],vec![]],retained:HashMap::new(),killers:HashMap::new(),slots:vec![],frames:vec![],record_frames:request["recordFrames"].as_bool().unwrap_or(true),logs:request["recordLogs"].as_bool().unwrap_or(true),other};for side in 0..if other{2}else{1}{combat.recruit(side,|r|r.sync_all())?;}let enemies=if request["enemies"].is_array(){request["enemies"].clone()}else{combat.games[1]["board"].clone()};for (side,board) in [combat.games[0]["board"].clone(),enemies.clone()].into_iter().enumerate(){for m in arr(&board){crate::validate_minion(m)?;let id=uid(m);if combat.cards.contains_key(&id){return Err("Combat minion UIDs must be unique across boards".into());}combat.boards[side].push(id.clone());combat.cards.insert(id,m.clone());}}combat.games[0]["season"]["lastDead"]=json!([]);combat.games[0]["season"]["lastEnemy"]=enemies;if other{combat.games[1]["season"]["lastDead"]=json!([]);combat.games[1]["season"]["lastEnemy"]=combat.games[0]["board"].clone();}for side in 0..2{for id in combat.boards[side].clone(){let health=num(&combat.m(&id)["health"]);bump(combat.mm(&id),"deathStatsHealth",health);combat.mm(&id)["counters"]["deathStatsHealth"]=json!(health);if has(combat.m(&id),"kodoStats")?{combat.mm(&id)["counters"]["kodoSummons"]=json!(0);}for key in ["piperDamage","pagleKill","avengeDeaths"]{combat.mm(&id)["counters"][key]=json!(0);}if truth(&combat.m(&id)["rebornNext"]){keyword(combat.mm(&id),"复生");}if side==0||other{let mut factor=if has(combat.m(&id),"keep")?{if truth(&combat.m(&id)["golden"]){2.}else{1.}}else{0.};if tribe(combat.m(&id),"龙")?{let i=combat.boards[side].iter().position(|x|x==&id).unwrap();for (j,x) in combat.boards[side].iter().enumerate(){if has(combat.m(x),"keepAllDragons")?||(i.abs_diff(j)==1&&has(combat.m(x),"keepAdjacentDragons")?){factor=f64::max(factor,if truth(&combat.m(x)["golden"]){2.}else{1.});}}}if factor>0.{combat.retained.insert(id.clone(),factor);}}}}let tier=request["enemyTier"].as_f64().unwrap_or(num(&combat.games[1]["tier"]));let battle=combat.fight(tier)?;let mut result=json!({"state":combat.games[0],"battle":battle,"rng":combat.rng.state,"draws":combat.rng.draws,"uidCounter":combat.serial});if other{result["other"]=combat.games[1].clone();}Ok(result)}
